def transform6(g):  # MST but tie-break: on equal length, prefer fewer blocks crossed
    import numpy as np
    H,W=len(g),len(g[0])
    A=np.array(g)
    seen=np.zeros_like(A,bool); blocks=[]
    for r in range(H):
        for c in range(W):
            if A[r,c]==2 and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=1; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and A[a,b]==2 and not seen[a,b]:
                            seen[a,b]=1; st.append((a,b))
                blocks.append(set(cells))
    ones=[(r,c) for r in range(H) for c in range(W) if g[r][c]==1]
    edges=[]
    for i,(r,c) in enumerate(ones):
        for j,(r2,c2) in enumerate(ones):
            if j<=i: continue
            if r==r2:
                seg={(r,cc) for cc in range(min(c,c2),max(c,c2)+1)}
                nb=sum(1 for bl in blocks if bl&seg)
                edges.append((c2-c,nb,i,j,'h',r,c,r2,c2))
            if c==c2:
                seg={(rr,c) for rr in range(min(r,r2),max(r,r2)+1)}
                nb=sum(1 for bl in blocks if bl&seg)
                edges.append((r2-r,nb,i,j,'v',r,c,r2,c2))
    edges.sort()
    parent=list(range(len(ones)))
    def find(x):
        while parent[x]!=x: x=parent[x]
        return x
    lines=set()
    for d,nb,i,j,_,r,c,r2,c2 in edges:
        a,b=find(i),find(j)
        if a!=b:
            parent[a]=b
            if _=='h':
                for cc in range(min(c,c2),max(c,c2)+1): lines.add((r,cc))
            else:
                for rr in range(min(r,r2),max(r,r2)+1): lines.add((rr,c))
    g2=[row[:] for row in g]
    for bl in blocks:
        if any(cell in lines for cell in bl):
            for x,y in bl: g2[x][y]=1
    for r,c in lines: g2[r][c]=1
    return g2
